{
  "id": "search-index-observability-001",
  "task": "Verify prefix search and incremental index observability are available through JSONL tool calls.",
  "setup": {
    "sources": [
      {
        "id": "source_search_index_contract",
        "type": "file",
        "locator": "docs/ARCHITECTURE.md",
        "title": "Search index observability contract"
      }
    ],
    "claims": [
      {
        "id": "claim_search_prefix_and_index_keys",
        "text": "SQLite FTS search supports safe prefix queries and incremental indexing reports affected document keys.",
        "type": "workflow",
        "status": "stable",
        "confidence": 0.9,
        "evidence": [
          "source_search_index_contract"
        ],
        "entities": [
          "SQLite",
          "FTS5",
          "prefix",
          "incremental indexing",
          "indexed_keys",
          "skipped_keys",
          "removed_keys"
        ],
        "scope": "project"
      }
    ],
    "tool_server_requests": [
      {
        "id": "incremental-index",
        "method": "akbp.index",
        "approved": true,
        "params": {
          "incremental": true
        },
        "expected_result_fields": [
          "ok",
          "db",
          "rows",
          "indexed",
          "skipped",
          "removed",
          "incremental",
          "indexed_keys",
          "skipped_keys",
          "removed_keys"
        ],
        "expected_result_values": {
          "ok": true,
          "incremental": true
        },
        "expected_result_schema": "#/$defs/index_result"
      },
      {
        "id": "prefix-search",
        "method": "akbp.search",
        "approved": false,
        "params": {
          "query": "pref* AND index*",
          "limit": 5
        },
        "expected_result_fields": [
          "query",
          "backend",
          "fts_query",
          "results"
        ],
        "expected_result_values": {
          "backend": "sqlite_fts5",
          "fts_query": "pref* AND index*"
        },
        "expected_result_schema": "#/$defs/search_result"
      }
    ]
  },
  "query": "How do prefix search and incremental indexing observability work?",
  "expected": {
    "must_retrieve": [
      "claim_search_prefix_and_index_keys"
    ],
    "must_cite": [
      "source_search_index_contract"
    ],
    "answer_should_include": [
      "prefix",
      "incremental indexing",
      "document keys"
    ],
    "must_apply_tool_methods": [
      "akbp.index"
    ]
  }
}

{
  "id": "secret-safety-001",
  "task": "Prevent secret-like values from being stored as durable claims.",
  "setup": {
    "sources": [
      {
        "id": "source_terminal_output",
        "type": "transcript",
        "locator": "sessions/output.md",
        "title": "Terminal output with accidental secret"
      }
    ],
    "proposed_claims": [
      {
        "text": "The deployment failed because OPENAI_API_KEY=sk-example1234567890 was missing in production.",
        "type": "blocker",
        "evidence": [
          "source_terminal_output"
        ],
        "scope": "project"
      }
    ],
    "tool_server_requests": [
      {
        "id": "source-title-redaction",
        "method": "akbp.source.add",
        "approved": true,
        "params": {
          "locator": "sessions/output.md",
          "type": "transcript",
          "title": "Terminal output OPENAI_API_KEY=sk-example1234567890"
        },
        "expected_result_fields": [
          "id",
          "type",
          "locator",
          "title",
          "immutable",
          "scope",
          "created_at",
          "metadata"
        ],
        "expected_result_values": {
          "title": "Terminal output [REDACTED]"
        },
        "expected_result_schema": "#/$defs/source_result"
      }
    ]
  },
  "query": "Store the durable blocker from the terminal output.",
  "expected": {
    "must_redact_patterns": [
      "sk-",
      "OPENAI_API_KEY="
    ],
    "must_not_store_raw_secret": true,
    "safe_claim_text": "The deployment failed because a required API key environment variable was missing in production."
  }
}

{
