        "entities": ["adapter", "crystallize", "handoff"],
        "scope": "project"
      },
      {
        "id": "claim_next_agent_should_run_validate",
        "text": "The next agent continuing this handoff should run make validate before pushing changes.",
        "type": "workflow",
        "status": "stable",
        "confidence": 0.9,
        "evidence": ["source_validation_log"],
        "entities": ["handoff", "validate", "next-agent"],
        "scope": "project"
      }
    ],
    "relations": [
      {
        "id": "relation_adapter_depends_on_tool_schema_refs",
        "source": "claim_adapter_docs_use_crystallize_shutdown",
        "target": "claim_tool_server_schema_refs_complete",
        "relation": "depends_on",
        "evidence": ["source_agent_b_session"]
      }
    ]
  },
  "query": "What should the next agent know for this handoff before updating adapters?",
  "expected": {
    "must_retrieve": [
      "claim_adapter_docs_use_crystallize_shutdown",
      "claim_next_agent_should_run_validate"
    ],
    "must_cite": [
      "source_agent_b_session",
      "source_validation_log"
    ],
    "answer_should_include": [
      "handoff",
      "adapter",
      "validate"
    ]
  }
}

{
  "id": "search-query-compatibility-001",
  "task": "Validate SQLite FTS query compatibility for phrase, version, hyphenated, slash-separated, dotted method-name, and empty search terms.",
  "setup": {
    "sources": [
      {
        "id": "source_search_query_compat",
        "type": "file",
        "locator": "docs/TOOL_CONTRACT.md",
        "title": "Tool contract search compatibility"
      }
    ],
    "claims": [
      {
        "id": "claim_search_query_compat",
        "text": "Python 3.12 and Node-22 compatible agents should use the JSONL tool-server contract, including akbp.session.start, for retrieval/search interop.",
        "type": "workflow",
        "status": "stable",
        "confidence": 0.9,
        "evidence": [
          "source_search_query_compat"
        ],
        "entities": [
          "Python 3.12",
          "Node-22",
          "JSONL",
          "tool-server",
          "retrieval/search",
          "akbp.session.start"
        ],
        "scope": "project"
      }
    ],
    "tool_server_requests": [
      {
        "id": "index-for-search-compat",
        "method": "akbp.index",
        "approved": true,
        "params": {
          "incremental": true
        },
        "expected_result_fields": [
          "ok",
          "db",
          "rows",
          "indexed",
          "skipped",
          "removed",
          "incremental",
          "indexed_keys",
          "skipped_keys",
          "removed_keys"
        ],
        "expected_result_values": {
          "ok": true,
          "incremental": true
        },
        "expected_result_schema": "#/$defs/index_result"
      },
      {
        "id": "phrase-version-hyphen-search",
        "method": "akbp.search",
        "params": {
          "query": "\"Python 3.12\" AND Node-22 AND JSONL",
          "limit": 5
        },
        "expected_result_fields": [
          "query",
          "backend",
          "fts_query",
          "results"
        ],
        "expected_result_values": {
          "backend": "sqlite_fts5",
          "fts_query": "\"Python 3.12\" AND \"Node-22\" AND \"JSONL\""
        },
        "expected_result_contains": {
          "results[].id": [
            "claim_search_query_compat"
          ]
        },
        "expected_result_schema": "#/$defs/search_result"
      },
      {
        "id": "slash-and-prefix-search",
        "method": "akbp.search",
        "params": {
          "query": "retrieval/search AND tool*",
          "limit": 5
        },
        "expected_result_fields": [
          "query",
          "backend",
          "fts_query",
          "results"
        ],
        "expected_result_values": {
          "backend": "sqlite_fts5",
          "fts_query": "\"retrieval/search\" AND tool*"
        },
        "expected_result_contains": {
          "results[].id": [
            "claim_search_query_compat"
          ]
        },
        "expected_result_schema": "#/$defs/search_result"
      },
      {
        "id": "mixed-operator-prefix-search",
        "method": "akbp.search",
        "params": {
          "query": "JSONL AND tool* OR Python*",
          "limit": 5
        },
        "expected_result_fields": [
          "query",
          "backend",
          "fts_query",
          "results"
        ],
        "expected_result_values": {
          "backend": "sqlite_fts5",
          "fts_query": "\"JSONL\" AND tool* OR Python*"
        },
        "expected_result_contains": {
          "results[].id": [
            "claim_search_query_compat"
          ]
        },
        "expected_result_schema": "#/$defs/search_result"
      },
      {
        "id": "dotted-method-search",
        "method": "akbp.search",
        "params": {
          "query": "akbp.session.start AND JSONL",
          "limit": 5
        },
        "expected_result_fields": [
          "query",
          "backend",
          "fts_query",
          "results"
        ],
        "expected_result_values": {
          "backend": "sqlite_fts5",
          "fts_query": "\"akbp.session.start\" AND \"JSONL\""
        },
        "expected_result_contains": {
          "results[].id": [
            "claim_search_query_compat"
          ]
        },
        "expected_result_schema": "#/$defs/search_result"
      },
      {
        "id": "leading-not-empty-search",
        "method": "akbp.search",
        "params": {
          "query": "NOT JSONL",
          "limit": 5
        },
        "expected_result_fields": [
          "query",
          "backend",
          "fts_query",
          "results"
        ],
        "expected_result_values": {
          "backend": "sqlite_fts5",
          "fts_query": "",
          "results": []
        },
        "expected_result_schema": "#/$defs/search_result"
      },
      {
        "id": "punctuation-empty-search",
        "method": "akbp.search",
        "params": {
          "query": "!!!",
          "limit": 5
        },
        "expected_result_fields": [
          "query",
          "backend",
          "fts_query",
          "results"
        ],
        "expected_result_values": {
          "backend": "sqlite_fts5",
          "fts_query": "",
          "results": []
        },
        "expected_result_schema": "#/$defs/search_result"
      },
      {
        "id": "operator-only-empty-search",
        "method": "akbp.search",
        "params": {
          "query": "AND OR NOT",
          "limit": 5
        },
        "expected_result_fields": [
          "query",
          "backend",
          "fts_query",
          "results"
        ],
        "expected_result_values": {
          "backend": "sqlite_fts5",
          "fts_query": "",
          "results": []
        },
        "expected_result_schema": "#/$defs/search_result"
      },
      {
        "id": "dangling-operator-search",
        "method": "akbp.search",
        "params": {
          "query": "JSONL AND",
          "limit": 5
        },
        "expected_result_fields": [
          "query",
          "backend",
          "fts_query",
          "results"
        ],
        "expected_result_values": {
          "backend": "sqlite_fts5",
          "fts_query": "\"JSONL\""
        },
        "expected_result_contains": {
          "results[].id": [
            "claim_search_query_compat"
          ]
        },
        "expected_result_schema": "#/$defs/search_result"
      }
    ]
  },
  "query": "How should Python 3.12 and Node-22 agents search JSONL tool-server knowledge?",
  "expected": {
    "must_retrieve": [
      "claim_search_query_compat"
    ],
    "must_cite": [
      "source_search_query_compat"
    ],
    "answer_should_include": [
      "Python 3.12",
      "Node-22",
      "JSONL",
      "tool-server",
      "retrieval/search",
      "akbp.session.start"
    ],
    "must_apply_tool_methods": [
      "akbp.index"
    ]
  }
}

{
  "id": "git-native-agent-handoff-001",
  "task": "Verify a git-native agent adapter can retrieve prior session constraints and review-gated write policy before continuing work.",
  "setup": {
    "sources": [
      {
        "id": "source_git_native_session",
        "type": "transcript",
        "locator": "sessions/git-native-agent-session.md",
        "title": "Git-native agent session handoff"
      },
      {
        "id": "source_adapter_policy",
        "type": "file",
        "locator": "adapters/git-native-agent/README.md",
        "title": "Git-native adapter policy"
      }
    ],
    "claims": [
      {
        "id": "claim_git_native_reads_context_first",
        "text": "Git-native agent adapters should retrieve cited AKBP context before planning substantial repository work.",
        "type": "workflow",
        "status": "stable",
        "confidence": 0.88,
        "evidence": [
          "source_git_native_session",
          "source_adapter_policy"
        ],
        "entities": [
          "git-native agent",
          "adapter",
          "context retrieval",
          "repository work"
        ],
        "scope": "project"
      },
      {
        "id": "claim_git_native_write_review_gate",
        "text": "Git-native agent adapters must preview durable memory writes with dry_run before applying them with approved:true.",
        "type": "workflow",
        "status": "stable",
        "confidence": 0.9,
        "evidence": [
          "source_adapter_policy"
        ],
        "entities": [
          "git-native agent",
          "dry_run",
          "approved:true",
          "review-gated writes"
        ],
        "scope": "project"
      }
    ],
    "tool_server_requests": [
      {
        "id": "session-start-git-native",
        "method": "akbp.session.start",
        "params": {
          "task": "continue git-native agent repository work with safe memory writes",
          "limit": 5
        },
        "expected_result_fields": [
          "session_id",
          "context"
        ],
        "expected_result_contains": {
          "context.items[].id": [
            "claim_git_native_reads_context_first",
            "claim_git_native_write_review_gate"
          ]
        },
        "expected_result_schema": "#/$defs/session_start_result"
      },
      {
        "id": "context-git-native-write-policy",
        "method": "akbp.context",
        "params": {
          "task": "git-native adapter dry_run approved write policy",
          "limit": 5
        },
        "expected_result_fields": [
          "query",
          "items"
        ],
        "expected_result_contains": {
          "items[].id": [
            "claim_git_native_write_review_gate"
          ]
        },
        "expected_result_schema": "#/$defs/context_result"
      }
    ]
  },
  "query": "What should a git-native adapter do before planning and applying durable memory writes?",
  "expected": {
    "must_retrieve": [
      "claim_git_native_reads_context_first",
      "claim_git_native_write_review_gate"
    ],
    "must_cite": [
      "source_git_native_session",
      "source_adapter_policy"
    ],
    "answer_should_include": [
      "cited AKBP context",
      "dry_run",
      "approved:true",
      "review-gated"
    ]
  }
}

{
  "id": "retrieval-citation-bundle-001",
  "task": "Verify retrieval returns the claim whose evidence can be cited through the JSONL tool server.",
  "setup": {
    "sources": [
      {
        "id": "source_release_risk_note",
        "type": "file",
        "locator": "notes/release-risk.md",
